import java.util.*;

class Solution {
    public int[] sortArray(int[] nums) {
        // insertion sort: nums[0..i-1] is sorted before each step
        for (int i = 1; i < nums.length; i++) {
            int key = nums[i];
            int j = i - 1;
            while (j >= 0 && nums[j] > key) {   // shift bigger values right
                nums[j + 1] = nums[j];
                j--;
            }
            nums[j + 1] = key;                  // drop key into the gap
        }
        return nums;
    }
}

